#: What the real model must do with these words (edit: this is the spec of the fix).
EXPECT = {
    # WA-277 step A: a different issue at a site that has one saved today is its own issue.
    "must_call": ["report_issue"],
    "must_not_call": ["tell_the_team"],
}


async def test_replay_second_issue_same_site() -> None:
    turn, _api = await replay(RECORDED)
    # WA-277 step A: the trace of that day does not keep everything the code reads around the model (the site
    # they were on, the catalogue and unit reads), so this pins what TODAY's code does with the same calls;
    # what production held then is in RECORDED["pending"]. The live test below is the guard of the behaviour.
    assert [c["tool"] for c in turn.calls] == ['report_issue']
    assert [e.summary for e in turn.pending] == ['Helmet missing issue, Site B']


@pytest.mark.nightly  # the full set only, to keep the everyday eval small
@pytest.mark.live
async def test_replay_second_issue_same_site_live() -> None:
    turn, _api = await replay(RECORDED, live=True)
    assert check(turn, EXPECT) == []
